{
  "settings": {
    "number_of_shards": 1,
    "number_of_replicas": 0,
    "analysis": {
      "analyzer": {
        "lab_text": {
          "type": "custom",
          "char_filter": [
            "html_strip"
          ],
          "tokenizer": "standard",
          "filter": [
            "lowercase",
            "asciifolding"
          ]
        }
      },
      "normalizer": {
        "lab_fold": {
          "type": "custom",
          "filter": [
            "lowercase",
            "asciifolding"
          ]
        }
      }
    }
  },
  "mappings": {
    "dynamic": "strict",
    "_source": {
      "enabled": true
    },
    "_meta": {
      "lab_revision": "2026-10-08",
      "execution_status": "NOT_RUN"
    },
    "runtime": {
      "price_with_tax": {
        "type": "double",
        "script": {
          "source": "if (doc['price'].size() != 0) emit(doc['price'].value * 1.1);"
        }
      }
    },
    "properties": {
      "id": {
        "type": "keyword",
        "store": true
      },
      "title": {
        "type": "text",
        "analyzer": "lab_text",
        "search_analyzer": "lab_text",
        "search_quote_analyzer": "lab_text",
        "index_options": "offsets",
        "norms": true,
        "similarity": "BM25",
        "term_vector": "with_positions_offsets",
        "index_phrases": true,
        "index_prefixes": {
          "min_chars": 2,
          "max_chars": 5
        },
        "position_increment_gap": 100,
        "copy_to": "all_text",
        "meta": {
          "purpose": "全文、完整值、词数对照"
        },
        "fields": {
          "raw": {
            "type": "keyword",
            "normalizer": "lab_fold",
            "ignore_above": 256,
            "eager_global_ordinals": true
          },
          "english": {
            "type": "text",
            "analyzer": "english"
          },
          "count": {
            "type": "token_count",
            "analyzer": "lab_text"
          }
        }
      },
      "message": {
        "type": "text",
        "analyzer": "lab_text",
        "copy_to": "all_text"
      },
      "all_text": {
        "type": "text",
        "analyzer": "lab_text"
      },
      "body_light": {
        "type": "match_only_text"
      },
      "token_stats": {
        "type": "text",
        "fielddata": true,
        "fielddata_frequency_filter": {
          "min": 0,
          "max": 1,
          "min_segment_size": 0
        }
      },
      "no_positions": {
        "type": "text",
        "index_options": "freqs"
      },
      "no_norms": {
        "type": "text",
        "norms": false
      },
      "status": {
        "type": "keyword",
        "normalizer": "lab_fold",
        "null_value": "unknown"
      },
      "tenant": {
        "type": "constant_keyword",
        "value": "lab"
      },
      "path": {
        "type": "wildcard"
      },
      "tags": {
        "type": "keyword"
      },
      "required_tags": {
        "type": "integer"
      },
      "tiny_label": {
        "type": "keyword",
        "ignore_above": 4
      },
      "indexed_only": {
        "type": "keyword",
        "doc_values": false
      },
      "source_only": {
        "type": "keyword",
        "index": false,
        "doc_values": false
      },
      "cold_metric": {
        "type": "long",
        "index": false,
        "doc_values": true
      },
      "enabled": {
        "type": "boolean",
        "null_value": false
      },
      "i8": {
        "type": "byte"
      },
      "i16": {
        "type": "short"
      },
      "i32": {
        "type": "integer"
      },
      "i64": {
        "type": "long"
      },
      "u64": {
        "type": "unsigned_long"
      },
      "f32": {
        "type": "float"
      },
      "f64": {
        "type": "double"
      },
      "f16": {
        "type": "half_float"
      },
      "money": {
        "type": "scaled_float",
        "scaling_factor": 100
      },
      "price": {
        "type": "double",
        "coerce": true
      },
      "malformed_number": {
        "type": "integer",
        "ignore_malformed": true
      },
      "created_at": {
        "type": "date",
        "format": "strict_date_optional_time||epoch_millis"
      },
      "created_nanos": {
        "type": "date_nanos"
      },
      "client_ip": {
        "type": "ip"
      },
      "release": {
        "type": "version"
      },
      "blob": {
        "type": "binary",
        "store": true,
        "doc_values": true
      },
      "profile": {
        "type": "object",
        "dynamic": false,
        "properties": {
          "region": {
            "type": "keyword"
          }
        }
      },
      "attributes": {
        "type": "flattened",
        "depth_limit": 20
      },
      "users_object": {
        "type": "object",
        "properties": {
          "name": {
            "type": "keyword"
          },
          "role": {
            "type": "keyword"
          }
        }
      },
      "users": {
        "type": "nested",
        "dynamic": "strict",
        "include_in_parent": false,
        "include_in_root": false,
        "properties": {
          "name": {
            "type": "text",
            "fields": {
              "keyword": {
                "type": "keyword"
              }
            }
          },
          "role": {
            "type": "keyword"
          }
        }
      },
      "opaque": {
        "type": "object",
        "enabled": false
      },
      "literal_metrics": {
        "type": "object",
        "subobjects": false,
        "properties": {
          "time.max": {
            "type": "long"
          },
          "time.min": {
            "type": "long"
          }
        }
      },
      "integer_span": {
        "type": "integer_range"
      },
      "long_span": {
        "type": "long_range"
      },
      "float_span": {
        "type": "float_range"
      },
      "double_span": {
        "type": "double_range"
      },
      "date_span": {
        "type": "date_range",
        "format": "strict_date_optional_time"
      },
      "ip_span": {
        "type": "ip_range"
      },
      "location": {
        "type": "geo_point"
      },
      "area": {
        "type": "geo_shape"
      },
      "xy": {
        "type": "point"
      },
      "xy_area": {
        "type": "shape"
      },
      "suggestion": {
        "type": "completion",
        "analyzer": "simple",
        "preserve_separators": true,
        "preserve_position_increments": true,
        "max_input_length": 50
      },
      "autocomplete": {
        "type": "search_as_you_type",
        "max_shingle_size": 3
      },
      "embedding": {
        "type": "dense_vector",
        "dims": 3,
        "element_type": "float",
        "index": true,
        "similarity": "cosine",
        "index_options": {
          "type": "hnsw",
          "m": 16,
          "ef_construction": 100
        }
      },
      "sparse": {
        "type": "sparse_vector"
      },
      "popularity": {
        "type": "rank_feature",
        "positive_score_impact": true
      },
      "features": {
        "type": "rank_features"
      },
      "latency_hist": {
        "type": "histogram"
      },
      "latency_metrics": {
        "type": "aggregate_metric_double",
        "metrics": [
          "min",
          "max",
          "sum",
          "value_count"
        ],
        "default_metric": "max"
      },
      "id_alias": {
        "type": "alias",
        "path": "id"
      }
    }
  }
}

